// Hydrate full chapter notes from the pipeline-generated study decks.
//
// Geography and Home Economics are generated by the exam pipeline, which emits
// rich term/definition decks rather than hand-written *-content.js sidecars.
// Keep one source of truth by adapting those decks into the notes shape at load
// time instead of copying hundreds of definitions into a second generated file.
(function () {
  if (typeof COURSE_DATA === "undefined") return;

  var supportedSubjects = new Set(["geography", "home-economics"]);
  var decks = globalThis.FLASHCARDS_DB || {};

  COURSE_DATA.chapters.forEach(function (chapter) {
    if (!supportedSubjects.has(chapter.subject)) return;

    var cards = Array.isArray(decks[chapter.id]) ? decks[chapter.id] : [];
    if (!cards.length || !Array.isArray(chapter.learningOutcomes) || !chapter.learningOutcomes.length) return;

    var hasNotes = chapter.learningOutcomes.some(function (outcome) {
      return Array.isArray(outcome.notes) && outcome.notes.length > 0;
    });
    if (hasNotes) return;

    var outcome = chapter.learningOutcomes[0];
    outcome.notes = cards
      .filter(function (card) { return card && (card.term || card.definition); })
      .map(function (card) {
        return {
          h: card.term || "Key idea",
          b: card.definition || "",
        };
      });

    // The chapter list and Full Notes screen should draw from the same vetted
    // material. Preserve the richer generated metadata on the study cards.
    if (!Array.isArray(outcome.keyTerms) || !outcome.keyTerms.length) {
      outcome.keyTerms = cards.slice();
    }
  });
})();
